python3 - <<'"'PY'
from pathlib import Path
import xml.etree.ElementTree as ET
path = Path.home()/'.config/libreoffice/4/user/registrymodifications.xcu'
ET.register_namespace('oor', 'http://openoffice.org/2001/registry')
ns = {'oor': 'http://openoffice.org/2001/registry'}
tree = ET.parse(path)
root = tree.getroot()

def set_item(item_path, props):
    target = None
    for item in root.findall('item'):
        if item.get('{http://openoffice.org/2001/registry}path') == item_path:
            target = item
            break
    if target is None:
        target = ET.SubElement(root, 'item', {'{http://openoffice.org/2001/registry}path': item_path})
    existing = {p.get('{http://openoffice.org/2001/registry}name'): p for p in target.findall('prop')}
    for name, value in props.items():
        prop = existing.get(name)
        if prop is None:
            prop = ET.SubElement(target, 'prop', {
                '{http://openoffice.org/2001/registry}name': name,
                '{http://openoffice.org/2001/registry}op': 'fuse',
            })
        else:
            prop.set('{http://openoffice.org/2001/registry}op', 'fuse')
        val = prop.find('value')
        if val is None:
            val = ET.SubElement(prop, 'value')
        val.text = value

set_item('/org.openoffice.Office.Common/Save/Document', {
    'AutoSave': 'true',
    'AutoSaveTimeIntervall': '3',
})
set_item('/org.openoffice.Office.Recovery/AutoSave', {
    'Enabled': 'true',
    'UserAutoSaveEnabled': 'true',
    'TimeIntervall': '3',
})
tree.write(path, encoding='UTF-8', xml_declaration=True)
PY
rg -n \"Office.Common/Save/Document|Office.Recovery/AutoSave|AutoSave|AutoSaveTimeIntervall|TimeIntervall|UserAutoSaveEnabled\" ~/.config/libreoffice/4/user/registrymodifications.xcu | head -20"

